 const int32 Start=FMath::Min(R.BlockIndex,Issues.Num()),End=Start+FMath::Min(R.Count,Issues.Num()-Start); FString Json; auto J=TJsonWriterFactory<>::Create(&Json); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("reachable_folder_structure_valid"),Complete && IssueCount==0); J->WriteValue(TEXT("reachable_scan_complete"),Complete); J->WriteValue(TEXT("visited_folder_count"),FolderCount); J->WriteValue(TEXT("inspected_track_reference_count"),TrackCount); J->WriteValue(TEXT("inspected_binding_reference_count"),BindingCount); J->WriteValue(TEXT("issue_count"),IssueCount); J->WriteValue(TEXT("retained_issue_count"),Issues.Num()); J->WriteValue(TEXT("issues_truncated"),IssueCount>Issues.Num()); J->WriteValue(TEXT("next_start"),End); J->WriteValue(TEXT("has_more_retained_issues"),End<Issues.Num()); J->WriteArrayStart(TEXT("issues")); for(int32 K=Start;K<End;++K) { J->WriteObjectStart(); J->WriteValue(TEXT("code"),Issues[K].Code); J->WriteValue(TEXT("folder_path"),Issues[K].Path); J->WriteValue(TEXT("detail"),Issues[K].Detail); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("scope"),TEXT("Bounded reachable native folder hierarchy structural validation: ownership/loading/class, repeated-cycle/multiple-parent membership, sibling name identity, current master-track membership, native scene binding GUID existence and duplicate content memberships. Max256 folders/depth32/members256 per folder/retained issues256/pages128; budget skips force incomplete/invalid. Does not find detached orphan UObjects, audit every binding body/external dependency, repair data, resolve players or prove UI/cook/runtime/persistence. No mutation/evaluation/playhead/events/render/compile/load/save; validation implementation unverified.")); J->WriteObjectEnd(); J->Close(); return Json;
